intro.body:
线性直接给 $\beta_t$；余弦先给 $\bar\alpha_t$ 再反推 $\beta_t$；EDM 用 $\sigma$ 公式排时间步。

```python
class LinearScheduler:
    def __init__(self, T=1000, beta_min=1e-4, beta_max=0.02):
        self.betas = torch.linspace(beta_min, beta_max, T)
        self.alphas = 1.0 - self.betas
        self.alpha_bars = torch.cumprod(self.alphas, dim=0)
    def snr(self, t):
        ab = self.alpha_bars[t].item()
        return ab / (1 - ab)
class CosineScheduler:
    def __init__(self, T=1000, s=0.008):
        ts = torch.arange(T + 1, dtype=torch.float32) / T
        f = torch.cos((ts + s) / (1 + s) * torch.pi / 2) ** 2
        self.alpha_bars = (f / f[0]).clamp(min=1e-8)[:T]
        prev = torch.cat([torch.tensor([1.0]), self.alpha_bars[:-1]])
        self.betas = (1.0 - self.alpha_bars / prev).clamp(max=0.999)
def edm_sigmas(n=40, smin=0.002, smax=80.0, rho=7.0):
    i = torch.arange(n + 1, dtype=torch.float32)
    s = (smax**(1/rho) + i/n * (smin**(1/rho) - smax**(1/rho)))**rho
    s[-1] = 0.0
    return s
```
